// Regenerates catalog-data/familiarity.js from the wordfreq corpus (Robyn Speer et al.),
// which estimates how often each answer appears in everyday English text.
// Usage: pip install wordfreq, then: npm run familiarity
// The game reads the generated file; Python is only needed to regenerate it.
import {execFileSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
import {events} from '../prompts.js';
import {expandedGroups} from '../coverage.js';
import {normalize} from '../matching.js';

const spellings=new Map();
for(const [,entries] of events)for(const [prompt,raw] of entries){
  for(const names of expandedGroups(prompt.split('\n')[0],raw))for(const name of names){
    const key=normalize(name);
    if(key && !/^\d+$/.test(key) && !spellings.has(key))spellings.set(key,name);
  }
}
const python=process.env.PYTHON||'python3';
const script=`import sys,json
from wordfreq import zipf_frequency
names=json.load(sys.stdin)
print(json.dumps({k:round(zipf_frequency(v,'en'),2) for k,v in names.items()}))`;
const scores=JSON.parse(execFileSync(python,['-c',script],{input:JSON.stringify(Object.fromEntries(spellings)),maxBuffer:1<<28}));
const kept=Object.fromEntries(Object.entries(scores).filter(([,z])=>z>0).sort(([a],[b])=>a<b?-1:1));
writeFileSync(new URL('../catalog-data/familiarity.js',import.meta.url),
  '// Generated by scripts/familiarity.mjs from wordfreq Zipf frequencies (log10 of uses per billion words).\n'+
  '// Spellings missing here scored 0, meaning the corpus has essentially never seen them.\n'+
  'export const familiarity='+JSON.stringify(kept)+';\n');
console.log('Scored',spellings.size,'spellings;',Object.keys(kept).length,'found in the corpus.');
